warp_.source:
shader_body
{
uv = frac(uv);
float2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw * 1 + rand_frame.xy;
float2 d = texsize.zw*12;
float3 dx = GetBlur3(uv_orig + float2(1,0)*d) - GetBlur3(uv_orig -float2(1,0)*d);
float3 dy = GetBlur3(uv_orig + float2(0,1)*d) - GetBlur3(uv_orig -float2(0,1)*d);

float2 uvx = uv
           + (tex2D(sampler_noise_lq, dither_uv).xy-0.5)*texsize.zw*0
           - float2(dx.x,dy.x)*texsize.zw*8;
    ret.x = tex2D( sampler_fc_main, uvx ).x
          - (GetBlur3(uvx)-tex2D( sampler_fc_main, uvx )).x*0.1
          - 0.024;

float2 uvy = uv_orig
           + (tex2D(sampler_noise_lq, dither_uv).xy-0.5)*texsize.zw*4
           - float2(dx.x,dy.x)*texsize.zw*4
           + float2(dx.y,dy.y)*texsize.zw*8;

ret.y = tex2d(sampler_fc_main,uvy).y
      + (tex2D(sampler_noise_lq, dither_uv).xyz-0.5)*0.1
      - 0.012
      + (tex2d(sampler_pc_main,uv_orig).z)*0.2;


float2 uvz = uv_orig
           + (tex2D(sampler_noise_lq, dither_uv).xy-0.5)*texsize.zw*2
           + float2(dy.x,-dx.x)*texsize.zw*64
           + float2(dx.z,dy.z)*texsize.zw*0;
ret.z = tex2d(sampler_fc_main,uvz).z
      + (tex2d(sampler_fc_main,uvz).z-GetBlur2(uvz).z)*0.2 
      + (tex2D(sampler_noise_lq, dither_uv).xyz)*0.1
      - GetBlur3(uv_orig).x
      - saturate(1-GetBlur2(uv_orig).x)*0.04;
}

